// Timer
useEffect(() => {
  const isTestMode = false; // 👉 true = teste 30s, false = produção

  let endTime: number;
  const now = new Date();

  if (isTestMode) {
    // Modo teste → 30s
    endTime = new Date().getTime() + 30 * 1000;
  } else {
    // Sorteio no dia 15 às 23:59:59
    const target = new Date(
      now.getFullYear(),
      now.getMonth(),
      15,
      23,
      59,
      59
    );

    // Se já passou do dia 15 deste mês → vai pro próximo mês
    if (target.getTime() < now.getTime()) {
      endTime = new Date(
        now.getFullYear(),
        now.getMonth() + 1,
        15,
        23,
        59,
        59
      ).getTime();
    } else {
      endTime = target.getTime();
    }
  }

  const interval = setInterval(() => {
    const now = new Date().getTime();
    const diff = endTime - now;

    if (diff <= 0) {
      setTimeLeft("00:00:00");
      clearInterval(interval);

      if (!drawDone) {
        drawWinners(5);
      }
    } else {
      const days = Math.floor(diff / (1000 * 60 * 60 * 24));
      const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const minutes = Math.floor((diff / (1000 * 60)) % 60);
      const seconds = Math.floor((diff / 1000) % 60);
      setTimeLeft(`${days}d ${hours}h ${minutes}m ${seconds}s`);
    }
  }, 1000);

  return () => clearInterval(interval);
}, [participants, drawDone]);
